  toast(msg) { this.setState({ toastMsg: msg }); clearTimeout(this._toastT); this._toastT = setTimeout(() => this.setState({ toastMsg: '' }), 2200); }

  // On load: prime CSRF cookie, then restore an existing session if there is one.
  bootstrapSession() {
    api.getCsrf().catch(() => {});
    api.me()
      .then((user) => this.applySession(user))
      .catch(() => {}); // not logged in -> stay on the login screen
  }

  componentDidMount() {
    this._onResize = () => this.setState({ vw: window.innerWidth });
    window.addEventListener('resize', this._onResize); this._onResize();
    this._onKey = (e) => { if (e.key === 'Escape') { if (this.state.ctxMenu) this.closeCtxMenu(); else if (this.state.modal) this.closeModal(); else if (this.state.drawerOpen) this.closeDrawer(); } };
    window.addEventListener('keydown', this._onKey);
    this.bootstrapSession();
    try {
      const raw = localStorage.getItem('floppydisk-state');
      if (raw) { const d = JSON.parse(raw); this.setState({ files: d.files || this.state.files, channels: d.channels || this.state.channels, posts: d.posts || this.state.posts, usedGB: d.usedGB != null ? d.usedGB : this.state.usedGB, profileName: d.profileName || this.state.profileName, profileUsername: d.profileUsername || this.state.profileUsername, profileBio: d.profileBio || this.state.profileBio, emailVerified: d.emailVerified != null ? d.emailVerified : this.state.emailVerified, phoneVerified: d.phoneVerified != null ? d.phoneVerified : this.state.phoneVerified }); }
    } catch (e) {}
  }
  componentWillUnmount() { if (this._onResize) window.removeEventListener('resize', this._onResize); if (this._onKey) window.removeEventListener('keydown', this._onKey); clearInterval(this._videoTimer); }
  _persist() { try { const s = this.state; localStorage.setItem('floppydisk-state', JSON.stringify({ files: s.files, channels: s.channels, posts: s.posts, usedGB: s.usedGB, profileName: s.profileName, profileUsername: s.profileUsername, profileBio: s.profileBio, emailVerified: s.emailVerified, phoneVerified: s.phoneVerified })); } catch (e) {} }
  componentDidUpdate() { clearTimeout(this._pT); this._pT = setTimeout(() => this._persist(), 400); }

