  // Adopt a User payload from the backend into the app's session state.
  applySession(user) {
    this.setState({
      authView: 'app', authError: '', authPassword: '',
      accountEmail: user.email,
      emailVerified: !!user.email_verified,
      profileName: user.display_name || this.state.profileName,
      billingEnabled: !!user.billing_enabled,
    });
    this.loadStorage();
    this.loadUsage();
    this.loadChannels();
    this.loadNotifications();
  }

  // Real quota/usage for the sidebar meter (falls back to demo values on failure).
  loadUsage() {
    api.usage()
      .then((u) => this.setState({
        realUsedBytes: u.used_bytes != null ? u.used_bytes : 0,
        realQuotaBytes: u.quota_bytes != null ? u.quota_bytes : null,
        realTierLabel: TIER_LABELS[u.tier] || (u.tier ? String(u.tier) : null),
      }))
      .catch(() => {});
  }

  loadNotifications() {
    api.notifications()
      .then((r) => this.setState({ unreadCount: r.unread_count || 0 }))
      .catch(() => {});
  }

  authPrimary() {
    const s = this.state, v = s.authView;
    if (s.authBusy) return;
    const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s.authEmail.trim());
    if (v === 'login') {
      if (!emailOk) return this.setState({ authError: 'Enter a valid email address' });
      if (!s.authPassword) return this.setState({ authError: 'Enter your password' });
      this.setState({ authBusy: true, authError: '' });
      api.login(s.authEmail.trim(), s.authPassword)
        .then((user) => { this.setState({ authBusy: false }); this.applySession(user); })
        .catch((err) => this.setState({ authBusy: false, authError: firstError(err, 'Incorrect email or password') }));
    } else if (v === 'register') {
      if (!s.authName.trim()) return this.setState({ authError: 'Enter your full name' });
      if (!emailOk) return this.setState({ authError: 'Enter a valid email address' });
      if (s.authPassword.length < 8) return this.setState({ authError: 'Password must be at least 8 characters' });
      if (!s.authDob) return this.setState({ authError: 'Enter your date of birth' });
      this.setState({ authBusy: true, authError: '' });
      api.register({ email: s.authEmail.trim(), password: s.authPassword, display_name: s.authName.trim(), date_of_birth: s.authDob })
        .then((user) => { this.setState({ authBusy: false }); this.applySession(user); this.toast('Welcome to Floppy Disk'); })
        .catch((err) => this.setState({ authBusy: false, authError: firstError(err, 'Could not create account') }));
    } else if (v === 'forgot') {
      if (!emailOk) return this.setState({ authError: 'Enter a valid email address' });
      this.setState({ authBusy: true, authError: '' });
      api.passwordReset(s.authEmail.trim())
        .then(() => { this.setState({ authBusy: false, authView: 'login' }); this.toast('If that email exists, a reset link is on its way'); })
        .catch(() => { this.setState({ authBusy: false, authView: 'login' }); this.toast('If that email exists, a reset link is on its way'); });
    }
  }
  authSkip() { const v = this.state.authView; if (v === 'verifyEmail') this.setState({ authView: 'verifyPhone', authCode: '' }); else this.setState({ authView: 'app' }); }
  toastForgot() { this.toast('Password reset link sent'); }
  toastResend() { this.toast('A new code has been sent'); }

