  updatePassword() { const { pwNew, pwConfirm } = this.state; if (!pwNew) { this.toast('Enter a new password'); return; } if (pwNew !== pwConfirm) { this.toast('Passwords do not match'); return; } this.setState({ pwCurrent: '', pwNew: '', pwConfirm: '' }); this.toast('Password updated'); }
  verifyEmailModal() { this.setState({ modal: 'verify', verifyType: 'email', verifyCode: '' }); }
  verifyPhoneModal() { this.setState({ modal: 'verify', verifyType: 'phone', verifyCode: '' }); }
  setVerifyCode(e) { this.setState({ verifyCode: e.target.value }); }
  confirmVerify() { const t = this.state.verifyType; if (t === 'email') this.setState({ emailVerified: true, modal: 'settings', settingsTab: 'account' }); else this.setState({ phoneVerified: true, modal: 'settings', settingsTab: 'account' }); this.toast((t === 'email' ? 'Email' : 'Phone') + ' verified'); }
  backToSettings() { this.setState({ modal: 'settings', settingsTab: 'account' }); }

  openComposer() {
    const ch = this.state.channels.find(c => c.subscribed && c.isAdmin) || this.state.channels.find(c => c.isAdmin);
    this.setState({ modal: 'composer', activeChannelId: ch ? ch.id : null, composerText: '', composerAttach: null });
  }
  setComposerText(e) { this.setState({ composerText: e.target.value }); }
  attachPhoto() { this.setState({ composerAttach: { type: 'image', poster: `https://picsum.photos/seed/new${Date.now()}/720/440` } }); }
  attachVideo() { this.setState({ composerAttach: { type: 'video', poster: `https://picsum.photos/seed/newv${Date.now()}/720/440`, videoSrc: 'https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerMeltdowns.mp4', duration: '0:15' } }); }
  attachFile() { this.setState({ composerAttach: { type: 'file', fileName: 'attachment.pdf', fileSize: '320 KB', docUrl: 'https://mozilla.github.io/pdf.js/web/compressed.tracemonkey-pldi-09.pdf' } }); }
  clearAttach() { this.setState({ composerAttach: null }); }
  submitPost() {
    const { composerText, composerAttach, activeChannelId } = this.state;
    if (!composerText.trim() && !composerAttach) { this.toast('Write something first'); return; }
    const a = composerAttach;
    const post = { id: 'post-' + Date.now(), channelId: activeChannelId, time: 'now', media: a ? a.type : 'none', text: composerText.trim(), poster: a && a.poster, videoSrc: a && a.videoSrc, duration: a && a.duration, fileName: a && a.fileName, fileSize: a && a.fileSize, docUrl: a && a.docUrl, views: '0', viewsNum: 0, likes: 0, sharesNum: 0, liked: false, own: true, comments: [] };
    this.setState(s => ({ posts: [post, ...s.posts], modal: null, composerText: '', composerAttach: null }));
    this.toast('Posted to channel');
  }
