  // Real upload: reserve quota -> PUT bytes to the presigned URL -> commit/dedup.
  realUpload(f) {
    const kind = kindOf(f.type || '');
    const qid = 'up-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7);
    const cur = this.state.currentFolderId;
    const inFolder = typeof cur === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(cur);
    this.setState(s => ({ uploadQueue: [...s.uploadQueue, { id: qid, name: f.name, progress: 15 }], modal: null }));
    api.initiateUpload({ name: f.name, size_bytes: f.size, kind, ...(inFolder ? { folder: cur } : {}) })
      .then((res) => api.uploadBytes(res.upload.url, f).then(() => api.completeUpload(res.file.id)))
      .then((file) => {
        const nf = {
          id: file.id, name: file.name, kind: file.kind, parentId: file.folder || null,
          size: humanSize(file.size_bytes), modified: 'Just now',
          shared: false, channel: false, starred: false, trashed: false, real: true,
        };
        this.setState(s => ({ files: [nf, ...s.files.filter(x => x.id !== qid)], uploadQueue: s.uploadQueue.filter(u => u.id !== qid) }));
        this.toast('Uploaded');
      })
      .catch((err) => {
        this.setState(s => ({ uploadQueue: s.uploadQueue.filter(u => u.id !== qid) }));
        this.toast(firstError(err, 'Upload failed'));
      });
  }

  simulateUpload() {
    const P = (s) => `https://picsum.photos/seed/${s}/640/420`;
    const specs = [{ name: 'sunset-clip.mp4', kind: 'video', poster: P('sunset' + Date.now()), videoSrc: 'https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerMeltdowns.mp4', duration: '0:15' }, { name: 'contract-final.pdf', kind: 'doc', docUrl: 'https://mozilla.github.io/pdf.js/web/compressed.tracemonkey-pldi-09.pdf' }];
    const items = specs.map((n, i) => ({ ...n, id: 'up-' + Date.now() + '-' + i, progress: 0 }));
    this.setState(s => ({ uploadQueue: [...s.uploadQueue, ...items.map(it => ({ id: it.id, name: it.name, progress: 0 }))] }));
    items.forEach(item => {
      const timer = setInterval(() => {
        this.setState(s => {
          const q = s.uploadQueue.map(u => u.id === item.id ? { ...u, progress: Math.min(100, u.progress + Math.round(10 + Math.random() * 20)) } : u);
          const done = q.find(u => u.id === item.id && u.progress >= 100);
          if (done) { clearInterval(timer); const nf = { id: item.id, name: item.name, kind: item.kind, parentId: s.currentFolderId, size: item.kind === 'video' ? '128 MB' : '1.4 MB', modified: 'Just now', duration: item.duration || null, poster: item.poster, videoSrc: item.videoSrc, docUrl: item.docUrl, watchedPct: 0, shared: false, channel: false, starred: false, trashed: false, recentRank: 0 }; setTimeout(() => { this.setState(s2 => ({ files: [nf, ...s2.files], uploadQueue: s2.uploadQueue.filter(u => u.id !== item.id) })); this.addUsage(item.kind === 'video' ? 0.13 : 0.01); }, 500); }
          return { uploadQueue: q };
        });
      }, 350);
    });
  }

